fn common_routes() -> Router<Arc<AppState>> {
    Router::new()
        .route("/health", get(health_check))
        .route("/v1/node/capabilities", get(node_capabilities))
        .route("/v1/node/identity", get(node_identity))
        .route("/v1/openapi.yaml", get(openapi_spec))
        .layer(tower_http::set_header::SetResponseHeaderLayer::overriding(
            header::SERVER,
            HeaderValue::from_static("froglet"),
        ))
        .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))
}

pub fn public_router(state: Arc<AppState>) -> Router {
    // NOTE: Per-IP rate limiting requires axum 0.8+ and tower_governor.
    // The provider_routes already enforce ConcurrencyLimitLayer(16) which
    // limits total in-flight requests. When upgrading to axum 0.8, add
    // tower_governor::GovernorLayer for per-caller throttling.
    let base = common_routes()
        .merge(events_query_routes(&state))
        .merge(provider_routes())
        .merge(publication_canary_routes())
        .merge(provider_control_routes(&state))
        .merge(publish_routes());

    // Hosted-trial routes are present on the public listener only when the
    // worker/origin shared secret is configured. Missing or incorrect secrets
    // return a generic 404 so `ai.froglet.dev` no longer exposes the trial
    // ingress directly.
    let router = if state.config.hosted_trial_origin_secret.is_some() {
        base.merge(hosted_trial_origin_routes(state.clone()))
    } else {
        base
    };
    router
        .layer(middleware::from_fn_with_state(
            state.clone(),
            relay_ingress_guard,
        ))
        .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))
        .with_state(state)
}

pub fn runtime_router(state: Arc<AppState>) -> Router {
    common_routes()
        .merge(runtime_routes(&state))
        .merge(execute_wasm_routes(&state))
        .merge(jobs_routes(&state))
        .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))
        .with_state(state)
}

/// Combined router with all routes (public + runtime). Used only in dual-mode
/// and in tests. **Do not use for internet-facing deployments**; use
/// `public_router` and `runtime_router` separately for production.
#[cfg_attr(
    not(test),
    deprecated(note = "use public_router + runtime_router for production")
)]
pub fn router(state: Arc<AppState>) -> Router {
    common_routes()
        .merge(events_query_routes(&state))
        .merge(runtime_routes(&state))
        .merge(provider_routes())
        .merge(publication_canary_routes())
        .merge(provider_control_routes(&state))
        .merge(publish_routes())
        .merge(execute_wasm_routes(&state))
        .merge(jobs_routes(&state))
        .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))
        .with_state(state)
}

