pub async fn node_capabilities(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let transport_status = state.transport_status.lock().await.clone();
    let settlement_descriptor = settlement::driver_descriptor(state.as_ref());
    let container_runtime_available = crate::oci_worker::ConfiguredOciWorker::from_env()
        .map(|worker| worker.is_enabled())
        .unwrap_or(false);
    let faas_descriptor = jobs::FaaSDescriptor::available(
        crate::python_sandbox::runtime_available(),
        container_runtime_available,
    );

    let capabilities = NodeCapabilities {
        api_version: "v1".to_string(),
        version: env!("CARGO_PKG_VERSION").to_string(),
        identity: IdentityInfo {
            node_id: state.identity.node_id().to_string(),
            public_key: state.identity.public_key_hex().to_string(),
        },
        discovery: DiscoveryInfo {
            mode: "none".to_string(),
        },
        transports: TransportsInfo {
            clearnet: ClearnetInfo {
                enabled: transport_status.clearnet_enabled,
                url: transport_status.clearnet_url,
            },
            tor: TorInfo {
                enabled: transport_status.tor_enabled,
                onion_url: transport_status.tor_onion_url,
                status: transport_status.tor_status,
            },
            relay: RelayInfo {
                enabled: transport_status.relay_enabled,
                control_url: state.config.relay.url.clone(),
                url: transport_status.relay_url,
                status: transport_status.relay_status,
            },
        },
        execution: ExecutionInfo {
            wasm: WasmInfo {
                enabled: true,
                fuel_limit: 50_000_000,
                entrypoints: vec!["alloc".to_string(), "run".to_string()],
            },
            gpu: GpuInfo {
                enabled: state.config.gpu.enabled,
                count: state.config.gpu.count,
                vendor: state.config.gpu.vendor.clone(),
                model: state.config.gpu.model.clone(),
                memory_mb: state.config.gpu.memory_mb,
                container_runtime: state.config.gpu.container_runtime.clone(),
                capabilities: state.config.gpu.advertised_capabilities(),
            },
        },
        limits: LimitsInfo {
            events_query_limit_default: 100,
            events_query_limit_max: 500,
            body_limit_bytes: MAX_BODY_BYTES,
            wasm_hex_limit_bytes: MAX_WASM_HEX_BYTES,
            wasm_input_limit_bytes: MAX_WASM_INPUT_BYTES,
            process_concurrency_limit: state.config.process_limits.concurrency,
            process_output_limit_bytes: state.config.process_limits.output_max_bytes,
            container_memory_limit_bytes: state.config.process_limits.memory_max_bytes,
            container_pids_limit: state.config.process_limits.pids_limit,
            container_cpu_limit: state.config.process_limits.cpu_limit,
            hosted_trial_deals_per_identity: state
                .config
                .public_quota
                .hosted_trial_deals_per_identity,
            hosted_trial_quota_window_secs: state.config.public_quota.hosted_trial_window_secs,
        },
        pricing: state.pricing.info().clone(),
        payments: PaymentsInfo {
            backend: settlement_descriptor.backend,
            verifier_mode: (settlement_descriptor.mode != "disabled")
                .then(|| settlement_descriptor.mode.clone()),
            accepted_payment_methods: settlement_descriptor.accepted_payment_methods,
            reservations: settlement_descriptor.reservations,
            receipts: settlement_descriptor.receipts,
        },
        faas: FaaSInfo {
            jobs_api: faas_descriptor.jobs_api,
            async_jobs: true,
            idempotency_keys: faas_descriptor.idempotency_keys,
            runtimes: faas_descriptor.runtimes,
        },
    };

    (StatusCode::OK, Json(capabilities))
}

