/// `GET /v1/runtime/spend` — requester spend policy and ledger totals.
pub async fn runtime_spend_status(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if let Err(error) = require_runtime_auth(&headers, state.as_ref()) {
        return error_json(error.0, error.1);
    }
    let totals = match state
        .db
        .with_write_conn(crate::requester_budget::spend_totals)
        .await
    {
        Ok(totals) => totals,
        Err(error) => {
            tracing::error!("spend ledger totals failed: {error}");
            return error_json(
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": "internal error" }),
            );
        }
    };
    let policy = state.config.requester_spend;
    let outstanding = totals.reserved_msat + totals.committed_msat;
    (
        StatusCode::OK,
        Json(json!({
            "max_deal_msat": policy.max_deal_msat,
            "spend_budget_msat": policy.spend_budget_msat,
            "reserved_msat": totals.reserved_msat,
            "committed_msat": totals.committed_msat,
            "remaining_msat": policy
                .spend_budget_msat
                .map(|budget| budget.saturating_sub(outstanding)),
        })),
    )
}

/// `POST /v1/runtime/spend/reset` — archive committed spend, restoring
/// cumulative budget headroom. In-flight reservations are left untouched.
pub async fn runtime_spend_reset(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if let Err(error) = require_runtime_auth(&headers, state.as_ref()) {
        return error_json(error.0, error.1);
    }
    let archived = match state
        .db
        .with_write_conn(|conn| {
            crate::requester_budget::reset_spend(conn, settlement::current_unix_timestamp())
        })
        .await
    {
        Ok(archived) => archived,
        Err(error) => {
            tracing::error!("spend ledger reset failed: {error}");
            return error_json(
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": "internal error" }),
            );
        }
    };
    (StatusCode::OK, Json(json!({ "archived_deals": archived })))
}

pub async fn runtime_wallet_balance(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if let Err(error) = require_runtime_auth(&headers, state.as_ref()) {
        return error_json(error.0, error.1);
    }

    match settlement::wallet_balance_snapshot(state.as_ref()).await {
        Ok(snapshot) => (
            StatusCode::OK,
            Json(json!(RuntimeWalletBalanceResponse {
                backend: snapshot.backend,
                mode: snapshot.mode,
                balance_known: snapshot.balance_known,
                balance_sats: snapshot.balance_sats,
                accepted_payment_methods: snapshot.accepted_payment_methods,
                reservations: snapshot.reservations,
                receipts: snapshot.receipts,
            })),
        ),
        Err(error) => error_json(error.status_code(), error.details()),
    }
}

/// Return a compact summary of recent requester-side deals and their
/// settlement state. Complements the per-deal `/v1/runtime/deals/:id`
/// endpoint with a list view; used by the MCP `list_settlement_activity`
/// action so an LLM can reason about pending/settled deals without knowing
/// specific deal ids.
pub async fn runtime_settlement_activity(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    axum::extract::Query(params): axum::extract::Query<SettlementActivityQuery>,
) -> impl IntoResponse {
    if let Err(error) = require_runtime_auth(&headers, state.as_ref()) {
        return error_json(error.0, error.1);
    }

    let limit = params
        .limit
        .unwrap_or(SETTLEMENT_ACTIVITY_DEFAULT_LIMIT)
        .clamp(1, SETTLEMENT_ACTIVITY_MAX_LIMIT);

    let records = match state
        .db
        .with_read_conn(move |conn| {
            crate::requester_deals::list_recent_requester_deals(conn, limit)
        })
        .await
    {
        Ok(records) => records,
        Err(error) => {
            return error_json(
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": format!("list requester deals: {error}") }),
            );
        }
    };

    let items: Vec<SettlementActivityItem> = records
        .iter()
        .map(|record| {
            let terms = &record.quote.payload.settlement_terms;
            SettlementActivityItem {
                deal_id: record.deal_id.clone(),
                provider_id: record.provider_id.clone(),
                status: record.status.clone(),
                workload_kind: record.spec.workload_kind().to_string(),
                settlement_method: terms.method.clone(),
                base_fee_msat: terms.base_fee_msat,
                success_fee_msat: terms.success_fee_msat,
                has_receipt: record.receipt.is_some(),
                has_result: record.result.is_some(),
                error: record.error.clone(),
                created_at: record.created_at,
                updated_at: record.updated_at,
            }
        })
        .collect();

    (
        StatusCode::OK,
        Json(json!(RuntimeSettlementActivityResponse { items, limit })),
    )
}

const SETTLEMENT_ACTIVITY_DEFAULT_LIMIT: usize = 25;
const SETTLEMENT_ACTIVITY_MAX_LIMIT: usize = 200;

#[derive(Debug, serde::Deserialize)]
pub struct SettlementActivityQuery {
    #[serde(default)]
    pub limit: Option<usize>,
}

fn format_reqwest_error(error: &reqwest::Error) -> String {
    let mut parts = vec![error.to_string()];
    let mut source: Option<&(dyn StdError + 'static)> = error.source();
    while let Some(next) = source {
        parts.push(next.to_string());
        source = next.source();
    }
    parts.join(": ")
}

async fn remote_json_request_with_pinned_addresses<T, B>(
    state: &AppState,
    method: reqwest::Method,
    url: String,
    body: Option<&B>,
    pinned_addresses: &[IpAddr],
) -> Result<T, ApiFailure>
where
    T: DeserializeOwned,
    B: Serialize + ?Sized,
{
    remote_json_request_inner(state, method, url, body, false, pinned_addresses).await
}

async fn remote_json_request_with_client_error_passthrough_and_pinned_addresses<T, B>(
    state: &AppState,
    method: reqwest::Method,
    url: String,
    body: Option<&B>,
    preserve_client_errors: bool,
    pinned_addresses: &[IpAddr],
) -> Result<T, ApiFailure>
where
    T: DeserializeOwned,
    B: Serialize + ?Sized,
{
    remote_json_request_inner(
        state,
        method,
        url,
        body,
        preserve_client_errors,
        pinned_addresses,
    )
    .await
}

async fn remote_json_request_inner<T, B>(
    state: &AppState,
    method: reqwest::Method,
    url: String,
    body: Option<&B>,
    preserve_client_errors: bool,
    pinned_addresses: &[IpAddr],
) -> Result<T, ApiFailure>
where
    T: DeserializeOwned,
    B: Serialize + ?Sized,
{
    let client = if pinned_addresses.is_empty() {
        state.http_client.clone()
    } else {
        pinned_json_client(state, &url, pinned_addresses).map_err(|error| {
            (
                StatusCode::BAD_GATEWAY,
                json!({ "error": "failed to pin upstream provider address", "details": error, "url": url }),
            )
        })?
    };
    let mut request = client.request(method, &url);
    if let Some(body) = body {
        request = request.json(body);
    }

    let response = request.send().await.map_err(|error| {
        (
            StatusCode::BAD_GATEWAY,
            json!({ "error": "upstream request failed", "details": format_reqwest_error(&error), "url": url }),
        )
    })?;
    let status = response.status();
    let body = crate::http_body::read_response_bytes_limited(
        response,
        MAX_UPSTREAM_JSON_BYTES,
        "upstream JSON response",
    )
    .await
    .map_err(|error| {
        (
            StatusCode::BAD_GATEWAY,
            json!({ "error": "failed to read upstream response", "details": error, "url": url }),
        )
    })?;
    let body_text = String::from_utf8_lossy(&body).into_owned();
    if !status.is_success() {
        if preserve_client_errors && status.is_client_error() {
            if let Ok(payload) = serde_json::from_slice::<Value>(&body) {
                return Err((status, payload));
            }
            return Err((
                status,
                json!({
                    "error": "upstream client error",
                    "upstream_body": body_text,
                    "url": url,
                }),
            ));
        }
        return Err((
            StatusCode::BAD_GATEWAY,
            json!({
                "error": "upstream request failed",
                "upstream_status": status.as_u16(),
                "upstream_body": body_text,
                "url": url,
            }),
        ));
    }
    serde_json::from_slice(&body).map_err(|error| {
        (
            StatusCode::BAD_GATEWAY,
            json!({ "error": "invalid upstream json", "details": error.to_string(), "url": url }),
        )
    })
}

const MARKETPLACE_ALLOW_LOCAL_HINT: &str =
    "set FROGLET_MARKETPLACE_ALLOW_LOCAL=1 only for explicit dev/test use";

async fn configured_marketplace_endpoint_for_egress(
    state: &AppState,
) -> Result<Option<provider_resolution::ValidatedRemoteEndpoint>, String> {
    let Some(raw_url) = state.config.marketplace_url.as_deref() else {
        return Ok(None);
    };
    provider_resolution::validate_remote_egress_url(
        raw_url,
        "FROGLET_MARKETPLACE_URL",
        state.config.marketplace_allow_local,
        MARKETPLACE_ALLOW_LOCAL_HINT,
    )
    .await
    .map(Some)
}

fn pinned_json_client(
    state: &AppState,
    url: &str,
    pinned_addresses: &[IpAddr],
) -> Result<reqwest::Client, String> {
    let parsed = reqwest::Url::parse(url).map_err(|error| format!("invalid URL: {error}"))?;
    let host = parsed
        .host_str()
        .ok_or_else(|| "URL must include a host".to_string())?;
    let port = parsed
        .port_or_known_default()
        .ok_or_else(|| "URL must include a known port".to_string())?;
    let socket_addresses: Vec<SocketAddr> = pinned_addresses
        .iter()
        .copied()
        .map(|address| SocketAddr::new(address, port))
        .collect();
    crate::tls::configured_reqwest_client_builder(state.config.http_ca_cert_path.as_deref())?
        .resolve_to_addrs(host, &socket_addresses)
        .build()
        .map_err(|error| format!("failed to build pinned client: {error}"))
}

async fn fetch_provider_descriptor(
    state: &AppState,
    provider: &provider_resolution::RuntimeProviderEndpoint,
) -> Result<SignedArtifact<DescriptorPayload>, ApiFailure> {
    remote_json_request_with_pinned_addresses(
        state,
        reqwest::Method::GET,
        format!("{}/v1/provider/descriptor", provider.url),
        Option::<&()>::None,
        &provider.pinned_public_addresses,
    )
    .await
}

fn provider_bad_gateway(message: &str) -> ApiFailure {
    (StatusCode::BAD_GATEWAY, json!({ "error": message }))
}

fn verify_remote_typed_artifact<T: Serialize>(
    artifact: &SignedArtifact<T>,
    expected_kind: &str,
) -> Result<(), String> {
    let document = serde_json::to_value(artifact)
        .map_err(|error| format!("failed to encode remote artifact: {error}"))?;
    protocol::verify_typed_document(&document, expected_kind)
        .map(|_| ())
        .map_err(|error| error.to_string())
}

fn verify_provider_descriptor_artifact(
    descriptor: &SignedArtifact<DescriptorPayload>,
) -> Result<(), ApiFailure> {
    if let Err(error) = verify_remote_typed_artifact(descriptor, ARTIFACT_KIND_DESCRIPTOR) {
        return Err(provider_bad_gateway(&format!(
            "provider descriptor validation failed: {error}"
        )));
    }
    Ok(())
}

fn verify_marketplace_quote_artifact(
    quote: SignedArtifact<QuotePayload>,
) -> Result<SignedArtifact<QuotePayload>, String> {
    verify_remote_typed_artifact(&quote, ARTIFACT_KIND_QUOTE)
        .map_err(|error| format!("marketplace quote validation failed: {error}"))?;
    Ok(quote)
}

pub(crate) fn verify_provider_receipt_artifact(
    receipt: &SignedArtifact<ReceiptPayload>,
    quote: &SignedArtifact<QuotePayload>,
    deal: &SignedArtifact<DealPayload>,
    expected_provider_id: &str,
    expected_requester_id: &str,
    result: Option<&Value>,
    result_hash: Option<&str>,
) -> Result<(), ApiFailure> {
    let report = protocol::validate_quote_deal_receipt(quote, deal, receipt, None);
    if !report.valid {
        let details = report
            .issues
            .iter()
            .map(|issue| format!("{}: {}", issue.code, issue.message))
            .collect::<Vec<_>>()
            .join("; ");
        return Err(provider_bad_gateway(&format!(
            "provider Artifact Chain validation failed: {details}"
        )));
    }
    if receipt.payload.provider_id != expected_provider_id {
        return Err(provider_bad_gateway(
            "provider receipt provider_id does not match selected provider",
        ));
    }
    if receipt.payload.requester_id != expected_requester_id {
        return Err(provider_bad_gateway(
            "provider receipt requester_id does not match local runtime identity",
        ));
    }
    match (receipt.payload.result_hash.as_deref(), result, result_hash) {
        (None, None, None) => {}
        (Some(receipt_hash), Some(result), Some(response_hash)) => {
            let canonical_hash = canonical_result_hash(result);
            if receipt_hash != response_hash || receipt_hash != canonical_hash {
                return Err(provider_bad_gateway(
                    "provider receipt, result_hash, and result payload do not match",
                ));
            }
        }
        _ => {
            return Err(provider_bad_gateway(
                "provider receipt result fields do not match the provider response",
            ));
        }
    }
    Ok(())
}

fn verify_provider_deal_artifact_chain(
    remote: &deals::DealRecord,
    expected_quote: &SignedArtifact<QuotePayload>,
    expected_deal: &SignedArtifact<DealPayload>,
) -> Result<(), ApiFailure> {
    if remote.quote.hash != expected_quote.hash || remote.deal.hash != expected_deal.hash {
        return Err(provider_bad_gateway(
            "provider deal does not match local requester artifacts",
        ));
    }
    let report = protocol::validate_quote_deal(&remote.quote, &remote.deal, None);
    if !report.valid {
        let details = report
            .issues
            .iter()
            .map(|issue| format!("{}: {}", issue.code, issue.message))
            .collect::<Vec<_>>()
            .join("; ");
        return Err(provider_bad_gateway(&format!(
            "provider Quote-to-Deal chain validation failed: {details}"
        )));
    }
    Ok(())
}

fn status_bound_to_receipt(receipt: &SignedArtifact<ReceiptPayload>) -> &'static str {
    match receipt.payload.deal_state.as_str() {
        "succeeded" => deals::DEAL_STATUS_SUCCEEDED,
        "rejected" => deals::DEAL_STATUS_REJECTED,
        "failed" | "canceled" => deals::DEAL_STATUS_FAILED,
        _ => unreachable!("canonical Receipt validation rejects unknown deal_state"),
    }
}

enum ProviderDealProjection {
    Unchanged,
    Provisional,
    SignedTerminal,
}

fn unsigned_provider_transition_is_forward(from: &str, to: &str) -> bool {
    match from {
        deals::DEAL_STATUS_PAYMENT_PENDING => matches!(
            to,
            deals::DEAL_STATUS_PAYMENT_PENDING
                | deals::DEAL_STATUS_ACCEPTED
                | deals::DEAL_STATUS_RUNNING
                | deals::DEAL_STATUS_RESULT_READY
        ),
        deals::DEAL_STATUS_ACCEPTED => matches!(
            to,
            deals::DEAL_STATUS_ACCEPTED
                | deals::DEAL_STATUS_RUNNING
                | deals::DEAL_STATUS_RESULT_READY
        ),
        deals::DEAL_STATUS_RUNNING => matches!(
            to,
            deals::DEAL_STATUS_RUNNING | deals::DEAL_STATUS_RESULT_READY
        ),
        deals::DEAL_STATUS_RESULT_READY => to == deals::DEAL_STATUS_RESULT_READY,
        _ => false,
    }
}

fn verify_provider_deal_projection(
    stored: &requester_deals::StoredRequesterDeal,
    remote: &deals::DealRecord,
) -> Result<ProviderDealProjection, ApiFailure> {
    verify_provider_deal_artifact_chain(remote, &stored.quote, &stored.deal)?;
    match remote.receipt.as_ref() {
        Some(receipt) => {
            verify_provider_receipt_artifact(
                receipt,
                &stored.quote,
                &stored.deal,
                &stored.provider_id,
                &stored.deal.payload.requester_id,
                remote.result.as_ref(),
                remote.result_hash.as_deref(),
            )?;
            if remote.status != status_bound_to_receipt(receipt) {
                return Err(provider_bad_gateway(
                    "provider status does not match its signed Receipt",
                ));
            }
            Ok(ProviderDealProjection::SignedTerminal)
        }
        None => {
            if !unsigned_provider_transition_is_forward(&stored.status, &remote.status) {
                return Err(provider_bad_gateway(
                    "provider attempted to change requester state without a signed Receipt",
                ));
            }
            match remote.status.as_str() {
                deals::DEAL_STATUS_RESULT_READY => {
                    let Some(result) = remote.result.as_ref() else {
                        return Err(provider_bad_gateway(
                            "provider result_ready projection is missing its result",
                        ));
                    };
                    let Some(result_hash) = remote.result_hash.as_deref() else {
                        return Err(provider_bad_gateway(
                            "provider result_ready projection is missing its result_hash",
                        ));
                    };
                    if canonical_result_hash(result) != result_hash || remote.error.is_some() {
                        return Err(provider_bad_gateway(
                            "provider result_ready projection has inconsistent result fields",
                        ));
                    }
                }
                _ if remote.result.is_some()
                    || remote.result_hash.is_some()
                    || remote.error.is_some() =>
                {
                    return Err(provider_bad_gateway(
                        "provider non-terminal projection has unexpected result or error fields",
                    ));
                }
                _ => {}
            }
            if remote.status == stored.status
                && remote.result == stored.result
                && remote.result_hash == stored.result_hash
                && remote.error == stored.error
            {
                Ok(ProviderDealProjection::Unchanged)
            } else {
                Ok(ProviderDealProjection::Provisional)
            }
        }
    }
}

struct ResolvedProvider {
    provider_id: String,
    provider_public_url: String,
    provider_sync_url: String,
    pinned_public_addresses: Vec<IpAddr>,
}

struct SyncedRequesterDeal {
    // A provisional remote result is for display only; CAS must compare the
    // durable state observed before the network request, never that projection.
    persisted: requester_deals::StoredRequesterDeal,
    deal: requester_deals::StoredRequesterDeal,
    provider_sync_url: String,
    pinned_public_addresses: Vec<IpAddr>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum RuntimeCreateDealScope {
    Full,
    HostedTrial { quota_identity: String },
}

impl RuntimeCreateDealScope {
    fn is_hosted_trial(&self) -> bool {
        matches!(self, Self::HostedTrial { .. })
    }

    fn quota_identity(&self) -> Option<&str> {
        match self {
            Self::HostedTrial { quota_identity } => Some(quota_identity.as_str()),
            Self::Full => None,
        }
    }
}

struct HostedTrialSession {
    _slot_id: usize,
}

async fn resolve_runtime_provider(
    state: &AppState,
    provider: &RuntimeProviderRef,
) -> Result<ResolvedProvider, ApiFailure> {
    let explicit_provider_id = provider.provider_id.clone();
    if let Some(provider_url) = provider.provider_url.clone() {
        let provider_endpoint = runtime_accessible_provider_endpoint(
            state,
            &provider_url,
            explicit_provider_id.as_deref(),
        )
        .await?;
        let descriptor = fetch_provider_descriptor(state, &provider_endpoint).await?;
        verify_provider_descriptor_artifact(&descriptor)?;
        if let Some(expected_provider_id) = explicit_provider_id.as_deref()
            && descriptor.payload.provider_id != expected_provider_id
        {
            return Err((
                StatusCode::BAD_REQUEST,
                json!({
                    "error": "provider_id does not match provider_url descriptor",
                    "provider_id": expected_provider_id,
                    "descriptor_provider_id": descriptor.payload.provider_id,
                }),
            ));
        }
        return Ok(ResolvedProvider {
            provider_id: descriptor.payload.provider_id.clone(),
            provider_public_url: provider_url,
            provider_sync_url: provider_endpoint.url,
            pinned_public_addresses: provider_endpoint.pinned_public_addresses,
        });
    }

    let Some(provider_id) = explicit_provider_id else {
        return Err((
            StatusCode::BAD_REQUEST,
            json!({ "error": "provider.provider_id or provider.provider_url is required" }),
        ));
    };
    // Discovery server has been removed.  Resolving a provider by ID alone
    // is no longer possible -- callers must supply a provider_url.
    Err((
        StatusCode::BAD_REQUEST,
        json!({
            "error": "provider.provider_url is required — discovery server removed; use marketplace or direct URL",
            "provider_id": provider_id,
        }),
    ))
}

fn hosted_trial_policy_error(message: &str) -> ApiFailure {
    (StatusCode::FORBIDDEN, json!({ "error": message }))
}

fn enforce_hosted_trial_create_deal_quota(
    state: &AppState,
    scope: &RuntimeCreateDealScope,
) -> Result<(), ApiFailure> {
    let Some(identity) = scope.quota_identity() else {
        return Ok(());
    };
    let Some(quota) = state.hosted_trial_deal_quota.as_ref() else {
        return Ok(());
    };
    match quota.check_and_increment(identity) {
        QuotaDecision::Allowed { .. } => Ok(()),
        QuotaDecision::Rejected { retry_after_secs } => Err((
            StatusCode::TOO_MANY_REQUESTS,
            json!({
                "error": "hosted trial create-deal quota exceeded",
                "retry_after_secs": retry_after_secs,
            }),
        )),
    }
}

fn normalized_public_quota_ip(value: &str) -> Option<String> {
    let mut value = value.trim().trim_matches('"').trim();
    if value.is_empty() {
        return None;
    }
    if let Some(stripped) = value.strip_prefix('[')
        && let Some((host, _)) = stripped.split_once(']')
    {
        value = host;
    } else if let Ok(socket_addr) = value.parse::<SocketAddr>() {
        return Some(socket_addr.ip().to_string());
    } else if value.matches(':').count() == 1
        && let Some((host, port)) = value.rsplit_once(':')
        && port.parse::<u16>().is_ok()
    {
        value = host.trim();
    }

    value.parse::<IpAddr>().ok().map(|ip| ip.to_string())
}

fn forwarded_public_quota_identity(headers: &HeaderMap) -> Option<String> {
    fn first_header_value(headers: &HeaderMap, name: &str) -> Option<String> {
        headers
            .get(name)
            .and_then(|value| value.to_str().ok())
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    }

    if let Some(forwarded_for) = first_header_value(headers, "x-forwarded-for")
        && let Some(first) = forwarded_for.split(',').next().map(str::trim)
        && let Some(ip) = normalized_public_quota_ip(first)
    {
        return Some(format!("origin:forwarded:{ip}"));
    }
    for header_name in ["cf-connecting-ip", "x-real-ip"] {
        if let Some(value) = first_header_value(headers, header_name)
            && let Some(ip) = normalized_public_quota_ip(&value)
        {
            return Some(format!("origin:forwarded:{ip}"));
        }
    }
    if let Some(forwarded) = first_header_value(headers, "forwarded") {
        for entry in forwarded.split(',') {
            for part in entry.split(';') {
                let part = part.trim();
                if let Some((name, value)) = part.split_once('=')
                    && name.eq_ignore_ascii_case("for")
                    && let Some(ip) = normalized_public_quota_ip(value)
                {
                    return Some(format!("origin:forwarded:{ip}"));
                }
            }
        }
    }
    None
}

pub(crate) fn public_quota_identity_from_request(
    headers: &HeaderMap,
    peer_addr: Option<SocketAddr>,
    trust_forwarded_headers: bool,
) -> String {
    if trust_forwarded_headers && let Some(identity) = forwarded_public_quota_identity(headers) {
        return identity;
    }
    if let Some(peer_addr) = peer_addr {
        return format!("origin:peer:{}", peer_addr.ip());
    }
    "origin:anonymous".to_string()
}

pub(crate) fn enforce_identity_quota(
    quota: &crate::public_quota::IdentityQuota,
    identity: &str,
    label: &str,
) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
    match quota.check_and_increment(identity) {
        QuotaDecision::Allowed { .. } => Ok(()),
        QuotaDecision::Rejected { retry_after_secs } => Err(error_json(
            StatusCode::TOO_MANY_REQUESTS,
            json!({
                "error": format!("{label} quota exceeded"),
                "retry_after_secs": retry_after_secs,
            }),
        )),
    }
}

async fn validate_hosted_trial_raw_create_deal_request(
    state: &AppState,
    payload: &RuntimeCreateDealRequest,
) -> Result<(), ApiFailure> {
    if payload.payment.is_some() {
        return Err(hosted_trial_policy_error(
            "hosted trial deals do not accept payment payloads",
        ));
    }
    if payload.max_price_sats.is_some_and(|value| value != 0) {
        return Err(hosted_trial_policy_error(
            "hosted trial deals must be free and use max_price_sats=0",
        ));
    }
    let local_node_id = state.identity.node_id();
    if payload.provider.provider_id.as_deref() != Some(local_node_id) {
        return Err(hosted_trial_policy_error(
            "hosted trial deals can only target the local hosted provider",
        ));
    }
    let Some(provider_url) = payload.provider.provider_url.as_deref() else {
        return Err(hosted_trial_policy_error(
            "hosted trial deals require the local hosted provider_url",
        ));
    };
    let Some(local_provider_base_url) =
        provider_resolution::configured_runtime_provider_base_url()?
    else {
        return Err(hosted_trial_policy_error(
            "hosted trial local provider base URL is not configured",
        ));
    };

    let normalized_provider_url = provider_url.trim_end_matches('/');
    let local_provider_base_url = local_provider_base_url.trim_end_matches('/');
    if normalized_provider_url == local_provider_base_url {
        return Ok(());
    }
    if state
        .config
        .public_base_url
        .as_deref()
        .is_some_and(|public_url| normalized_provider_url == public_url.trim_end_matches('/'))
    {
        return Ok(());
    }
    let advertised_clearnet_url = state.transport_status.lock().await.clearnet_url.clone();
    if advertised_clearnet_url
        .as_deref()
        .is_some_and(|clearnet_url| normalized_provider_url == clearnet_url.trim_end_matches('/'))
    {
        return Ok(());
    }

    Err(hosted_trial_policy_error(
        "hosted trial provider_url must target the local hosted provider",
    ))
}

fn validate_hosted_trial_workload_matches_service(
    spec: &WorkloadSpec,
    service: &ProviderServiceRecord,
) -> Result<(), String> {
    let WorkloadSpec::Execution { execution } = spec else {
        return Err(
            "hosted trial deal requests must use an execution workload for a free local service"
                .to_string(),
        );
    };
    let (runtime, package_kind, entrypoint_kind, entrypoint, contract_version) =
        normalized_service_execution_profile(service)?;
    if runtime == ExecutionRuntime::Builtin && package_kind == ExecutionPackageKind::Builtin {
        if service_binding_hash(service).is_some() {
            return validate_service_addressed_execution_against_service(execution, service);
        }
        if execution.runtime != runtime {
            return Err("hosted trial builtin runtime does not match local service".to_string());
        }
        if execution.package_kind != package_kind {
            return Err(
                "hosted trial builtin package_kind does not match local service".to_string(),
            );
        }
        if execution.entrypoint.kind != entrypoint_kind {
            return Err(
                "hosted trial builtin entrypoint_kind does not match local service".to_string(),
            );
        }
        if execution.entrypoint.value != entrypoint {
            return Err("hosted trial builtin entrypoint does not match local service".to_string());
        }
        if execution.contract_version != contract_version {
            return Err(
                "hosted trial builtin contract_version does not match local service".to_string(),
            );
        }
        if execution.workload_kind != service.offer_kind {
            return Err(
                "hosted trial builtin workload_kind does not match local service".to_string(),
            );
        }
        if execution.builtin_name.as_deref() != Some(entrypoint.as_str()) {
            return Err("hosted trial builtin name does not match local service".to_string());
        }
        if !execution.mounts.is_empty() {
            return Err("hosted trial builtin requests cannot include mounts".to_string());
        }
        return Ok(());
    }

    validate_service_addressed_execution_against_service(execution, service)
}

async fn validate_hosted_trial_free_local_offer(
    state: &AppState,
    payload: &RuntimeCreateDealRequest,
    provider: &ResolvedProvider,
) -> Result<(), ApiFailure> {
    if provider.provider_id != state.identity.node_id() {
        return Err(hosted_trial_policy_error(
            "hosted trial deals can only target the local hosted provider",
        ));
    }

    let Some(offer_record) = provider_control_offer_record(state, &payload.offer_id, false)
        .await
        .map_err(|error| {
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": "failed to load local provider offer", "details": error }),
            )
        })?
    else {
        return Err(hosted_trial_policy_error(
            "hosted trial offer is not an active local free service",
        ));
    };

    validate_hosted_trial_local_offer_record(state, &offer_record, &payload.spec).await
}

async fn validate_hosted_trial_local_offer_record(
    state: &AppState,
    offer_record: &ProviderControlOfferRecord,
    spec: &WorkloadSpec,
) -> Result<(), ApiFailure> {
    let Some(service_id) = offer_record.service_id.as_deref() else {
        return Err(hosted_trial_policy_error(
            "hosted trial offers must be provider-managed services",
        ));
    };
    if !state
        .config
        .session_pool
        .hosted_trial_allowed_service_ids
        .contains(service_id)
    {
        return Err(hosted_trial_policy_error(
            "hosted trial service is outside the public demo catalog",
        ));
    }
    if offer_record.publication_state != "active"
        || offer_record.offer.payload.settlement_method != "none"
        || offer_record.offer.payload.price_schedule.base_fee_msat != 0
        || offer_record.offer.payload.price_schedule.success_fee_msat != 0
    {
        return Err(hosted_trial_policy_error(
            "hosted trial offer is not an active local free service",
        ));
    }

    let Some(service) = provider_service_record(state, service_id, false, true)
        .await
        .map_err(|error| {
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": "failed to load local provider service", "details": error }),
            )
        })?
    else {
        return Err(hosted_trial_policy_error(
            "hosted trial offer is missing its local service binding",
        ));
    };
    if service.publication_state != "active"
        || service.price_sats != 0
        || service.provider_id != state.identity.node_id()
    {
        return Err(hosted_trial_policy_error(
            "hosted trial service is not active and free on the local provider",
        ));
    }
    validate_hosted_trial_workload_matches_service(spec, &service).map_err(|error| {
        (
            StatusCode::FORBIDDEN,
            json!({ "error": "hosted trial workload is outside the free demo scope", "details": error }),
        )
    })
}

async fn hosted_trial_offer_record_by_hash(
    state: &AppState,
    offer_hash: &str,
) -> Result<Option<ProviderControlOfferRecord>, String> {
    Ok(current_offer_records(state, false)
        .await?
        .into_iter()
        .find(|record| record.offer.hash == offer_hash))
}

fn validate_hosted_trial_quote_terms(
    quote: &SignedArtifact<QuotePayload>,
) -> Result<(), ApiFailure> {
    let terms = &quote.payload.settlement_terms;
    if terms.method == "none" && terms.base_fee_msat == 0 && terms.success_fee_msat == 0 {
        return Ok(());
    }
    Err((
        StatusCode::BAD_GATEWAY,
        json!({
            "error": "hosted trial provider returned non-free quote terms",
            "settlement_method": terms.method,
            "base_fee_msat": terms.base_fee_msat,
            "success_fee_msat": terms.success_fee_msat,
        }),
    ))
}

struct GeneratedSuccessPreimage {
    bytes: [u8; 32],
    encoded: String,
}

fn generate_success_preimage() -> GeneratedSuccessPreimage {
    let mut bytes = [0_u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut bytes);
    GeneratedSuccessPreimage {
        encoded: hex::encode(bytes),
        bytes,
    }
}

fn lightning_quote_max_admission_deadline(quote: &SignedArtifact<QuotePayload>) -> i64 {
    quote
        .payload
        .expires_at
        .saturating_sub(deal_execution_window_secs(&quote.payload.execution_limits) as i64)
        .saturating_sub(quote.payload.settlement_terms.max_success_hold_expiry_secs as i64)
}

fn build_runtime_requester_deal_artifact(
    state: &AppState,
    quote: &SignedArtifact<QuotePayload>,
    success_payment_hash: &str,
    created_at: i64,
    uses_lightning_bundle: bool,
) -> Result<SignedArtifact<DealPayload>, String> {
    let requester_id = state.identity.node_id().to_string();
    let execution_window_secs = deal_execution_window_secs(&quote.payload.execution_limits);
    let admission_deadline = if uses_lightning_bundle {
        lightning_quote_max_admission_deadline(quote).min(created_at.saturating_add(
            lightning_admission_window_secs(&quote.payload.settlement_terms) as i64,
        ))
    } else {
        quote.payload.expires_at
    };
    if uses_lightning_bundle && admission_deadline < created_at {
        return Err(
            "quote expiry already leaves no remaining Lightning admission window".to_string(),
        );
    }
    let completion_deadline = admission_deadline.saturating_add(execution_window_secs as i64);
    let acceptance_deadline = if uses_lightning_bundle {
        completion_deadline
            .saturating_add(quote.payload.settlement_terms.max_success_hold_expiry_secs as i64)
    } else {
        completion_deadline
    };

    if uses_lightning_bundle && acceptance_deadline > quote.payload.expires_at {
        return Err(
            "quote expiry is too short for the Lightning admission, execution, and acceptance windows"
                .to_string(),
        );
    }

    protocol::sign_artifact(
        &requester_id,
        |message| state.identity.sign_message_hex(message),
        ARTIFACT_KIND_DEAL,
        created_at,
        DealPayload {
            requester_id: requester_id.clone(),
            provider_id: quote.payload.provider_id.clone(),
            quote_hash: quote.hash.clone(),
            workload_hash: quote.payload.workload_hash.clone(),
            confidential_session_hash: quote.payload.confidential_session_hash.clone(),
            extension_refs: Vec::new(),
            authority_ref: None,
            supersedes_deal_hash: None,
            client_nonce: None,
            success_payment_hash: success_payment_hash.to_string(),
            admission_deadline,
            completion_deadline,
            acceptance_deadline,
        },
    )
}

fn persist_runtime_artifact(
    conn: &rusqlite::Connection,
    artifact_hash: &str,
    payload_hash: &str,
    artifact_kind: &str,
    actor_id: &str,
    created_at: i64,
    document_json: &str,
) -> Result<(), String> {
    db::insert_artifact_document(
        conn,
        artifact_hash,
        payload_hash,
        artifact_kind,
        actor_id,
        created_at,
        document_json,
    )
}

async fn persist_requester_artifacts(
    state: Arc<AppState>,
    quote: &SignedArtifact<QuotePayload>,
    deal: &SignedArtifact<DealPayload>,
    receipt: Option<&SignedArtifact<ReceiptPayload>>,
) -> Result<(), String> {
    let quote_json = serde_json::to_string(quote).map_err(|error| error.to_string())?;
    let deal_json = serde_json::to_string(deal).map_err(|error| error.to_string())?;
    let receipt_json = receipt
        .map(serde_json::to_string)
        .transpose()
        .map_err(|error| error.to_string())?;
    let quote = quote.clone();
    let deal = deal.clone();
    let receipt = receipt.cloned();
    state
        .db
        .with_write_conn(move |conn| {
            db::with_immediate_transaction(conn, |conn| {
                persist_runtime_artifact(
                    conn,
                    &quote.hash,
                    &quote.payload_hash,
                    &quote.artifact_type,
                    &quote.signer,
                    quote.created_at,
                    &quote_json,
                )?;
                persist_runtime_artifact(
                    conn,
                    &deal.hash,
                    &deal.payload_hash,
                    &deal.artifact_type,
                    &deal.signer,
                    deal.created_at,
                    &deal_json,
                )?;
                if let (Some(receipt), Some(receipt_json)) =
                    (receipt.as_ref(), receipt_json.as_ref())
                {
                    persist_runtime_artifact(
                        conn,
                        &receipt.hash,
                        &receipt.payload_hash,
                        &receipt.artifact_type,
                        &receipt.signer,
                        receipt.created_at,
                        receipt_json,
                    )?;
                }
                Ok(())
            })
        })
        .await
}

async fn sync_requester_deal_from_provider(
    state: Arc<AppState>,
    deal_id: &str,
) -> Result<SyncedRequesterDeal, ApiFailure> {
    let lookup_deal_id = deal_id.to_string();
    let stored = state
        .db
        .with_read_conn(move |conn| requester_deals::get_requester_deal(conn, &lookup_deal_id))
        .await
        .map_err(|error| {
            tracing::error!("database error fetching deal {deal_id}: {error}");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": "internal error" }),
            )
        })?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                json!({ "error": "deal not found", "deal_id": deal_id }),
            )
        })?;

    let provider_endpoint = runtime_accessible_provider_endpoint(
        state.as_ref(),
        stored.sync_provider_url(),
        Some(&stored.provider_id),
    )
    .await?;

    let remote: deals::DealRecord = remote_json_request_with_pinned_addresses(
        state.as_ref(),
        reqwest::Method::GET,
        format!(
            "{}/v1/provider/deals/{}",
            provider_endpoint.url,
            urlencoding::encode(deal_id)
        ),
        Option::<&()>::None,
        &provider_endpoint.pinned_public_addresses,
    )
    .await?;

    let projection = verify_provider_deal_projection(&stored, &remote)?;
    match projection {
        ProviderDealProjection::Unchanged => {
            return Ok(SyncedRequesterDeal {
                persisted: stored.clone(),
                deal: stored,
                provider_sync_url: provider_endpoint.url,
                pinned_public_addresses: provider_endpoint.pinned_public_addresses,
            });
        }
        ProviderDealProjection::Provisional => {
            let mut projected = stored.clone();
            projected.status = remote.status;
            projected.result = remote.result;
            projected.result_hash = remote.result_hash;
            projected.error = remote.error;
            return Ok(SyncedRequesterDeal {
                persisted: stored,
                deal: projected,
                provider_sync_url: provider_endpoint.url,
                pinned_public_addresses: provider_endpoint.pinned_public_addresses,
            });
        }
        ProviderDealProjection::SignedTerminal => {}
    }

    persist_requester_artifacts(
        state.clone(),
        &remote.quote,
        &remote.deal,
        remote.receipt.as_ref(),
    )
    .await
    .map_err(|error| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            json!({ "error": "failed to persist requester artifacts", "details": error }),
        )
    })?;

    let update_id = deal_id.to_string();
    let status = remote.status.clone();
    let result = remote.result.clone();
    let result_hash = remote.result_hash.clone();
    let error = remote.error.clone();
    let receipt = remote.receipt.clone();
    let expected_status = stored.status.clone();
    let expected_result = stored.result.clone();
    let expected_result_hash = stored.result_hash.clone();
    let expected_error = stored.error.clone();
    let expected_receipt_hash = stored.receipt.as_ref().map(|receipt| receipt.hash.clone());
    let expected_updated_at = stored.updated_at;
    let updated_at = settlement::current_unix_timestamp();
    let deal = state
        .db
        .with_write_conn(move |conn| {
            db::with_immediate_transaction(conn, |conn| {
                let Some(current) = requester_deals::get_requester_deal(conn, &update_id)? else {
                    return Ok(None);
                };
                let current_receipt_hash = current
                    .receipt
                    .as_ref()
                    .map(|receipt| receipt.hash.as_str());
                if current.status != expected_status
                    || current.result != expected_result
                    || current.result_hash != expected_result_hash
                    || current.error != expected_error
                    || current_receipt_hash != expected_receipt_hash.as_deref()
                    || current.updated_at != expected_updated_at
                {
                    return Ok(Some(current));
                }
                requester_deals::update_requester_deal_state(
                    conn,
                    &update_id,
                    &status,
                    result.as_ref(),
                    result_hash.as_deref(),
                    error.as_deref(),
                    receipt.as_ref(),
                    updated_at,
                )
            })
        })
        .await
        .map_err(|error| {
            tracing::error!("database error syncing deal {deal_id}: {error}");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": "internal error" }),
            )
        })?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                json!({ "error": "deal not found after sync", "deal_id": deal_id }),
            )
        })?;

    Ok(SyncedRequesterDeal {
        persisted: deal.clone(),
        deal,
        provider_sync_url: provider_endpoint.url,
        pinned_public_addresses: provider_endpoint.pinned_public_addresses,
    })
}

pub async fn hosted_trial_runtime_create_deal(
    State(state): State<Arc<AppState>>,
    connect_info: Option<ConnectInfo<SocketAddr>>,
    headers: HeaderMap,
    Json(payload): Json<RuntimeCreateDealRequest>,
) -> Response {
    if let Err(error) = require_hosted_trial_session_auth(&headers, state.as_ref()) {
        return error_json(error.0, error.1).into_response();
    }
    let quota_identity = public_quota_identity_from_request(
        &headers,
        connect_info.map(|ConnectInfo(peer_addr)| peer_addr),
        state.config.public_quota.trust_forward_public_quota_headers,
    );
    runtime_create_deal_inner(
        state,
        payload,
        RuntimeCreateDealScope::HostedTrial { quota_identity },
    )
    .await
}

pub async fn runtime_create_deal(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(payload): Json<RuntimeCreateDealRequest>,
) -> Response {
    if let Err(error) = require_runtime_auth(&headers, state.as_ref()) {
        return error_json(error.0, error.1).into_response();
    }
    runtime_create_deal_inner(state, payload, RuntimeCreateDealScope::Full).await
}

/// Holds a `reserved` row in the requester spend ledger until either the
/// attempt fails without an external side effect or it durably crosses that
/// boundary. Once marked `external_pending`, dropping this guard must never
/// release real or potentially-real spend.
struct SpendReservationGuard {
    state: Arc<AppState>,
    deal_hash: String,
    armed: bool,
}

impl SpendReservationGuard {
    fn new(state: Arc<AppState>, deal_hash: String) -> Self {
        Self {
            state,
            deal_hash,
            armed: true,
        }
    }

    async fn mark_external_pending(&mut self) -> Result<(), String> {
        if !self.armed {
            return Ok(());
        }
        let deal_hash = self.deal_hash.clone();
        self.state
            .db
            .with_write_conn(move |conn| {
                crate::requester_budget::mark_spend_external_pending(
                    conn,
                    &deal_hash,
                    settlement::current_unix_timestamp(),
                )
            })
            .await?;
        self.armed = false;
        Ok(())
    }

    async fn commit(mut self, deal_id: &str) {
        let deal_hash = self.deal_hash.clone();
        let deal_id = deal_id.to_string();
        match self
            .state
            .db
            .with_write_conn(move |conn| {
                crate::requester_budget::commit_spend(
                    conn,
                    &deal_hash,
                    &deal_id,
                    settlement::current_unix_timestamp(),
                )
            })
            .await
        {
            Ok(()) => self.armed = false,
            Err(error) => {
                // An external-pending row stays counted. If this was somehow
                // still only reserved, Drop may release it because no caller
                // should commit before crossing the external boundary.
                tracing::error!("failed to commit spend ledger reservation: {error}");
            }
        }
    }
}

impl Drop for SpendReservationGuard {
    fn drop(&mut self) {
        if !self.armed {
            return;
        }
        let state = self.state.clone();
        let deal_hash = std::mem::take(&mut self.deal_hash);
        tokio::spawn(async move {
            if let Err(error) = state
                .db
                .with_write_conn(move |conn| {
                    crate::requester_budget::release_spend(conn, &deal_hash)
                })
                .await
            {
                tracing::error!("failed to release spend ledger reservation: {error}");
            }
        });
    }
}

async fn runtime_create_deal_inner(
    state: Arc<AppState>,
    payload: RuntimeCreateDealRequest,
    scope: RuntimeCreateDealScope,
) -> Response {
    if let Err(response) = validate_workload_spec(&payload.spec) {
        return response.into_response();
    }
    if scope.is_hosted_trial()
        && let Err(error) =
            validate_hosted_trial_raw_create_deal_request(state.as_ref(), &payload).await
    {
        return error_json(error.0, error.1).into_response();
    }
    if let Err(error) = enforce_hosted_trial_create_deal_quota(state.as_ref(), &scope) {
        return error_json(error.0, error.1).into_response();
    }

    let idempotency_key = match normalize_idempotency_key(payload.idempotency_key.clone()) {
        Ok(key) => key,
        Err(response) => return response.into_response(),
    };

    // A completed or in-flight requester intent wins before fetching a new
    // Quote or contacting the provider Deal endpoint. This makes retries
    // return the durable operation instead of generating a new signed Deal,
    // spend reservation, or payment attempt.
    if let Some(key) = idempotency_key.as_deref() {
        let lookup_key = key.to_string();
        let existing = match state
            .db
            .with_read_conn(move |conn| {
                requester_deals::find_requester_deal_by_idempotency_key(conn, &lookup_key)
            })
            .await
        {
            Ok(existing) => existing,
            Err(error) => {
                tracing::error!("failed to look up requester idempotency key: {error}");
                return error_json(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    json!({ "error": "internal error" }),
                )
                .into_response();
            }
        };
        if let Some(existing) = existing {
            let provider_id_conflicts = payload
                .provider
                .provider_id
                .as_deref()
                .is_some_and(|provider_id| provider_id != existing.provider_id);
            let provider_url_conflicts =
                payload
                    .provider
                    .provider_url
                    .as_deref()
                    .is_some_and(|provider_url| {
                        let provider_url = provider_url.trim_end_matches('/');
                        provider_url != existing.provider_url.trim_end_matches('/')
                            && existing
                                .provider_sync_url
                                .as_deref()
                                .is_none_or(|sync_url| {
                                    provider_url != sync_url.trim_end_matches('/')
                                })
                    });
            if provider_id_conflicts || provider_url_conflicts || existing.spec != payload.spec {
                return error_json(
                    StatusCode::CONFLICT,
                    json!({ "error": "idempotency key reused with a different requester deal" }),
                )
                .into_response();
            }
            let stored_price = existing
                .quote
                .payload
                .settlement_terms
                .base_fee_msat
                .checked_add(existing.quote.payload.settlement_terms.success_fee_msat);
            if payload.max_price_sats.is_some_and(|maximum| {
                stored_price.is_none_or(|price| price > maximum.saturating_mul(1000))
            }) {
                return error_json(StatusCode::CONFLICT, json!({"error":"existing idempotent invocation exceeds the requested max_price_sats"})).into_response();
            }
            if scope.is_hosted_trial()
                && (existing.provider_id != state.identity.node_id()
                    || validate_hosted_trial_quote_terms(&existing.quote).is_err())
            {
                return error_json(
                    StatusCode::FORBIDDEN,
                    json!({ "error": "hosted trial idempotency key does not identify a free local deal" }),
                )
                .into_response();
            }

            let stored =
                match sync_requester_deal_from_provider(state.clone(), &existing.deal_id).await {
                    Ok(synced) => synced.deal,
                    Err(_) => existing,
                };
            let mut payment_intent = None;
            if quote_uses_lightning_bundle(state.as_ref(), &stored.quote) {
                match load_runtime_requester_deal_and_payment_intent(state.clone(), &stored.deal_id)
                    .await
                {
                    Ok((_deal, intent)) => payment_intent = intent,
                    Err(error) => return error_json(error.0, error.1).into_response(),
                }
            }
            return (
                StatusCode::OK,
                Json(json!(RuntimeCreateDealResponse {
                    provider_id: stored.provider_id.clone(),
                    provider_url: stored.provider_url.clone(),
                    quote: stored.quote.clone(),
                    deal: stored.public_record(),
                    payment_intent_path: payment_intent
                        .as_ref()
                        .map(|intent| runtime_payment_intent_path(&intent.deal_id)),
                    payment_intent,
                })),
            )
                .into_response();
        }
    }

    let provider = match resolve_runtime_provider(state.as_ref(), &payload.provider).await {
        Ok(provider) => provider,
        Err(error) => return error_json(error.0, error.1).into_response(),
    };
    if scope.is_hosted_trial()
        && let Err(error) =
            validate_hosted_trial_free_local_offer(state.as_ref(), &payload, &provider).await
    {
        return error_json(error.0, error.1).into_response();
    }
    let expected_workload_kind = payload.spec.workload_kind().to_string();
    let expected_workload_hash = match payload.spec.request_hash() {
        Ok(hash) => hash,
        Err(error) => {
            return error_json(
                StatusCode::BAD_REQUEST,
                json!({ "error": format!("failed to hash requested workload: {error}") }),
            )
            .into_response();
        }
    };
    let expected_confidential_session_hash =
        payload.spec.confidential_session_hash().map(str::to_string);

    let quote = match remote_json_request_with_pinned_addresses::<SignedArtifact<QuotePayload>, _>(
        state.as_ref(),
        reqwest::Method::POST,
        format!("{}/v1/provider/quotes", provider.provider_sync_url),
        Some(&CreateQuoteRequest {
            offer_id: payload.offer_id.clone(),
            requester_id: state.identity.node_id().to_string(),
            spec: payload.spec.clone(),
            max_price_sats: if scope.is_hosted_trial() {
                Some(0)
            } else {
                payload.max_price_sats
            },
        }),
        &provider.pinned_public_addresses,
    )
    .await
    {
        Ok(quote) => quote,
        Err(error) => return error_json(error.0, error.1).into_response(),
    };

    if !protocol::verify_artifact(&quote) {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({ "error": "provider quote signature verification failed" }),
        )
        .into_response();
    }
    if let Err(error) = verify_remote_typed_artifact(&quote, ARTIFACT_KIND_QUOTE) {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({
                "error": "provider quote validation failed",
                "details": error,
            }),
        )
        .into_response();
    }
    if quote.payload.provider_id != provider.provider_id {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({ "error": "provider quote provider_id does not match selected provider" }),
        )
        .into_response();
    }
    if quote.payload.requester_id != state.identity.node_id() {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({ "error": "provider quote requester_id does not match local runtime identity" }),
        )
        .into_response();
    }
    if quote.payload.workload_kind != expected_workload_kind {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({
                "error": "provider quote workload_kind does not match requested workload",
                "quote_workload_kind": quote.payload.workload_kind,
                "requested_workload_kind": expected_workload_kind,
            }),
        )
        .into_response();
    }
    if quote.payload.workload_hash != expected_workload_hash {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({
                "error": "provider quote workload_hash does not match requested workload",
                "quote_workload_hash": quote.payload.workload_hash,
                "requested_workload_hash": expected_workload_hash,
            }),
        )
        .into_response();
    }
    if quote.payload.confidential_session_hash != expected_confidential_session_hash {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({
                "error": "provider quote confidential_session_hash does not match requested workload",
                "quote_confidential_session_hash": quote.payload.confidential_session_hash,
                "requested_confidential_session_hash": expected_confidential_session_hash,
            }),
        )
        .into_response();
    }
    if scope.is_hosted_trial()
        && let Err(error) = validate_hosted_trial_quote_terms(&quote)
    {
        return error_json(error.0, error.1).into_response();
    }

    let generated_preimage = generate_success_preimage();
    let success_payment_hash = crypto::sha256_hex(generated_preimage.bytes);
    let success_preimage = generated_preimage.encoded;
    let deal_artifact = match build_runtime_requester_deal_artifact(
        state.as_ref(),
        &quote,
        &success_payment_hash,
        settlement::current_unix_timestamp(),
        quote_uses_lightning_bundle(state.as_ref(), &quote),
    ) {
        Ok(deal) => deal,
        Err(error) => {
            return error_json(StatusCode::BAD_REQUEST, json!({ "error": error })).into_response();
        }
    };

    // ── Requester spend policy ─────────────────────────────────────────────
    //
    // Enforced here — after quote verification, before any side effect — so
    // no settlement rail (SPT mint, deal contract, prepaid payment, bundle
    // invoices) can commit funds past the configured caps. The full quoted
    // total is reserved atomically against the cumulative budget; free deals
    // (total 0) skip the policy entirely. Fail-closed: paid deals are refused
    // when no budget is configured.
    let quoted_total_msat = match quote
        .payload
        .settlement_terms
        .base_fee_msat
        .checked_add(quote.payload.settlement_terms.success_fee_msat)
    {
        Some(total) if i64::try_from(total).is_ok() => total,
        _ => {
            return error_json(
                StatusCode::BAD_GATEWAY,
                json!({ "error": "provider quote total exceeds the supported signed range" }),
            )
            .into_response();
        }
    };
    if quote.payload.settlement_terms.method == "lightning.prepaid.v1"
        && quote.payload.settlement_terms.base_fee_msat % 1_000 != 0
    {
        return error_json(
            StatusCode::BAD_GATEWAY,
            json!({ "error": "prepaid Lightning quote amount must be a whole number of satoshis" }),
        )
        .into_response();
    }
    let mut spend_guard: Option<SpendReservationGuard> = None;
    if quoted_total_msat > 0 {
        // The provider also enforces the caller's max_price_sats, but a
        // misbehaving provider could ignore it — re-check the signed quote
        // locally before trusting its price.
        if let Some(max_price_sats) = payload.max_price_sats
            && quoted_total_msat > max_price_sats.saturating_mul(1_000)
        {
            return error_json(
                StatusCode::BAD_GATEWAY,
                json!({
                    "error": "provider quote exceeds the requested max_price_sats",
                    "quoted_total_msat": quoted_total_msat,
                    "max_price_msat": max_price_sats.saturating_mul(1_000),
                }),
            )
            .into_response();
        }

        let policy = state.config.requester_spend;
        let ledger_deal_hash = deal_artifact.hash.clone();
        let ledger_provider_id = provider.provider_id.clone();
        let ledger_method = quote.payload.settlement_terms.method.clone();
        let decision = match state
            .db
            .with_write_conn(move |conn| {
                crate::requester_budget::try_reserve_spend(
                    conn,
                    &policy,
                    &ledger_deal_hash,
                    &ledger_provider_id,
                    quoted_total_msat,
                    &ledger_method,
                    settlement::current_unix_timestamp(),
                )
            })
            .await
        {
            Ok(decision) => decision,
            Err(error) => {
                tracing::error!("spend ledger reservation failed: {error}");
                return error_json(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    json!({ "error": "internal error" }),
                )
                .into_response();
            }
        };
        match decision {
            crate::requester_budget::SpendDecision::Reserved => {
                spend_guard = Some(SpendReservationGuard::new(
                    state.clone(),
                    deal_artifact.hash.clone(),
                ));
            }
            crate::requester_budget::SpendDecision::Unconfigured => {
                return error_json(
                    StatusCode::PAYMENT_REQUIRED,
                    json!({
                        "error": "paid deals are disabled: no requester spend budget is \
                                  configured; set FROGLET_REQUESTER_SPEND_BUDGET_MSAT (and \
                                  optionally FROGLET_REQUESTER_MAX_DEAL_MSAT) to enable paid \
                                  deals on this node",
                        "code": "spend_budget_unconfigured",
                        "quoted_total_msat": quoted_total_msat,
                    }),
                )
                .into_response();
            }
            crate::requester_budget::SpendDecision::CapExceeded { max_deal_msat } => {
                return error_json(
                    StatusCode::PAYMENT_REQUIRED,
                    json!({
                        "error": format!(
                            "deal price {quoted_total_msat} msat exceeds the per-deal spend \
                             cap (FROGLET_REQUESTER_MAX_DEAL_MSAT={max_deal_msat})"
                        ),
                        "code": "spend_cap_exceeded",
                        "quoted_total_msat": quoted_total_msat,
                        "max_deal_msat": max_deal_msat,
                        "provider_id": provider.provider_id,
                    }),
                )
                .into_response();
            }
            crate::requester_budget::SpendDecision::BudgetExceeded {
                spend_budget_msat,
                spent_msat,
                remaining_msat,
            } => {
                return error_json(
                    StatusCode::PAYMENT_REQUIRED,
                    json!({
                        "error": format!(
                            "cumulative spend budget exhausted: {spent_msat} of \
                             {spend_budget_msat} msat committed; this deal needs \
                             {quoted_total_msat} msat. Raise \
                             FROGLET_REQUESTER_SPEND_BUDGET_MSAT or POST \
                             /v1/runtime/spend/reset."
                        ),
                        "code": "spend_budget_exceeded",
                        "quoted_total_msat": quoted_total_msat,
                        "spend_budget_msat": spend_budget_msat,
                        "spent_msat": spent_msat,
                        "remaining_msat": remaining_msat,
                    }),
                )
                .into_response();
            }
        }
    }
    // ── end requester spend policy ─────────────────────────────────────────

    // ── Buyer-side Stripe SPT minting ──────────────────────────────────────
    //
    // When the quote requires stripe_mpp.v1 payment, production callers must
    // supply an SPT issued by their authorized agentic-commerce platform. The
    // only automatic path is Stripe's seller-side test helper, guarded by an
    // explicit sandbox opt-in and an sk_test_ key in BuyerStripeConfig.
    //
    // If the caller explicitly supplied `payload.payment`, we honour it as-is
    // (allows advanced callers to pre-mint tokens externally).
    let payment_for_deal: Option<settlement::ProvidedPayment> = if quote
        .payload
        .settlement_terms
        .method
        == "stripe_mpp.v1"
    {
        match (&payload.payment, &state.config.buyer_stripe) {
            (Some(payment), _) => {
                if payment.kind != "stripe_mpp"
                    || !settlement::stripe::is_valid_spt_id(&payment.token)
                {
                    return error_json(
                            StatusCode::BAD_REQUEST,
                            json!({
                                "error": "stripe_mpp.v1 requires a caller-supplied Stripe Shared Payment Token",
                                "code": "invalid_stripe_spt",
                            }),
                        )
                        .into_response();
                }
                Some(payment.clone())
            }
            (None, None)
            | (
                None,
                Some(crate::config::BuyerStripeConfig {
                    test_helper_enabled: false,
                    ..
                }),
            ) => {
                return error_json(
                    StatusCode::PAYMENT_REQUIRED,
                    json!({
                        "error": "the provider requires Stripe payment (stripe_mpp.v1); \
                                  supply a Shared Payment Token issued by an authorized \
                                  agentic-commerce platform in payment.kind='stripe_mpp' and \
                                  payment.token",
                        "code": "stripe_spt_required",
                    }),
                )
                .into_response();
            }
            (None, Some(buyer_config)) => {
                // The quoted price is expressed in msat; convert to cents
                // (1 sat = 1 cent in this protocol — the unit is shared).
                // The SPT ceiling is padded by 1 cent to satisfy any
                // strict > check on the Stripe side.
                let price_cents = (quoted_total_msat / 1_000).max(1);
                // Give the token a 10-minute validity window — enough for
                // the provider to validate and create the PaymentIntent.
                let expires_at = match settlement::current_unix_timestamp().checked_add(600) {
                    Some(expires_at) => expires_at,
                    None => {
                        return error_json(
                            StatusCode::INTERNAL_SERVER_ERROR,
                            json!({ "error": "internal error" }),
                        )
                        .into_response();
                    }
                };

                if let Some(guard) = spend_guard.as_mut()
                    && let Err(error) = guard.mark_external_pending().await
                {
                    tracing::error!("failed to persist spend before SPT mint: {error}");
                    return error_json(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        json!({ "error": "internal error" }),
                    )
                    .into_response();
                }

                match settlement::mint_buyer_spt(
                    buyer_config,
                    price_cents,
                    expires_at,
                    buyer_config.api_base_url.as_deref(),
                )
                .await
                {
                    Ok(spt_id) => Some(settlement::ProvidedPayment {
                        kind: "stripe_mpp".to_string(),
                        token: spt_id,
                    }),
                    Err(err) => {
                        tracing::error!("Buyer SPT mint failed: {err}");
                        return error_json(
                            StatusCode::SERVICE_UNAVAILABLE,
                            json!({
                                "error": format!(
                                    "Stripe sandbox SPT test helper failed: {err}"
                                ),
                                "code": "stripe_spt_test_helper_failed",
                            }),
                        )
                        .into_response();
                    }
                }
            }
        }
    } else {
        payload.payment.clone()
    };
    // ── end buyer-side SPT minting ─────────────────────────────────────────

    // The provider Deal request is the first contractual external effect for
    // caller-supplied payments and all non-Stripe rails. Persist that boundary
    // before sending it so an error or crash cannot release actual spend.
    if let Some(guard) = spend_guard.as_mut()
        && let Err(error) = guard.mark_external_pending().await
    {
        tracing::error!("failed to persist spend before provider Deal request: {error}");
        return error_json(
            StatusCode::INTERNAL_SERVER_ERROR,
            json!({ "error": "internal error" }),
        )
        .into_response();
    }

    let remote_deal = match remote_json_request_with_pinned_addresses::<deals::DealRecord, _>(
        state.as_ref(),
        reqwest::Method::POST,
        format!("{}/v1/provider/deals", provider.provider_sync_url),
        Some(&CreateDealRequest {
            quote: quote.clone(),
            deal: deal_artifact.clone(),
            spec: payload.spec.clone(),
            idempotency_key: idempotency_key.clone(),
            payment: payment_for_deal,
        }),
        &provider.pinned_public_addresses,
    )
    .await
    {
        Ok(deal) => deal,
        Err(error) => return error_json(error.0, error.1).into_response(),
    };

    if let Err(error) = verify_provider_deal_artifact_chain(&remote_deal, &quote, &deal_artifact) {
        return error_json(error.0, error.1).into_response();
    }
    if let Some(receipt) = remote_deal.receipt.as_ref()
        && let Err(error) = verify_provider_receipt_artifact(
            receipt,
            &quote,
            &deal_artifact,
            &provider.provider_id,
            &deal_artifact.payload.requester_id,
            remote_deal.result.as_ref(),
            remote_deal.result_hash.as_deref(),
        )
    {
        return error_json(error.0, error.1).into_response();
    }

    // Validate every provider-controlled BOLT11 field against the signed Quote
    // before either persisting a payment intent or handing the invoice to the
    // buyer's wallet.
    let prepaid_invoice = if quote.payload.settlement_terms.method == "lightning.prepaid.v1" {
        let Some(invoice) = remote_deal.prepaid_invoice.as_ref() else {
            return error_json(
                StatusCode::BAD_GATEWAY,
                json!({
                    "error": "provider accepted a prepaid Lightning deal but did not return an invoice"
                }),
            )
            .into_response();
        };
        if state.config.buyer_phoenixd.is_none() {
            return error_json(
                StatusCode::PAYMENT_REQUIRED,
                json!({
                    "error": "the provider requires prepaid Lightning (lightning.prepaid.v1) but \
                              this buyer node has no phoenixd configured; set \
                              FROGLET_LIGHTNING_BUYER_PHOENIXD_URL and \
                              FROGLET_LIGHTNING_BUYER_PHOENIXD_HTTP_PASSWORD to enable \
                              buyer-side payments"
                }),
            )
            .into_response();
        }
        if let Err(error) = settlement::lightning::validate_prepaid_lightning_invoice(
            settlement::lightning::PrepaidLightningInvoiceValidation {
                invoice_bolt11: &invoice.bolt11,
                expected_payment_hash: &invoice.payment_hash,
                expected_amount_sat: invoice.amount_sat,
                expected_destination_identity: Some(
                    quote.payload.settlement_terms.destination_identity.as_str(),
                ),
                expected_network: Some(lightning_invoice::Currency::Bitcoin),
                now: settlement::current_unix_timestamp(),
                deal_admission_deadline: deal_artifact.payload.admission_deadline,
                quote: &quote,
            },
        ) {
            return error_json(
                StatusCode::BAD_GATEWAY,
                json!({
                    "error": "provider returned an invalid prepaid Lightning invoice",
                    "details": error,
                }),
            )
            .into_response();
        }
        Some(invoice.clone())
    } else {
        None
    };

    if let Err(error) = persist_requester_artifacts(
        state.clone(),
        &quote,
        &deal_artifact,
        remote_deal.receipt.as_ref(),
    )
    .await
    {
        return error_json(
            StatusCode::INTERNAL_SERVER_ERROR,
            json!({ "error": "failed to persist requester artifacts", "details": error }),
        )
        .into_response();
    }

    let created_at = settlement::current_unix_timestamp();
    let insert_deal_id = remote_deal.deal_id.clone();
    let provider_id = provider.provider_id.clone();
    let provider_public_url = provider.provider_public_url.clone();
    let provider_sync_url = provider.provider_sync_url.clone();
    let insert_outcome = match state
        .db
        .with_write_conn(move |conn| {
            requester_deals::insert_or_get_requester_deal(
                conn,
                NewRequesterDeal {
                    deal_id: insert_deal_id,
                    idempotency_key: idempotency_key.clone(),
                    provider_id,
                    provider_url: provider_public_url,
                    provider_sync_url: Some(provider_sync_url),
                    spec: payload.spec.clone(),
                    quote: quote.clone(),
                    deal: deal_artifact.clone(),
                    status: remote_deal.status.clone(),
                    success_preimage,
                    created_at,
                },
            )
        })
        .await
    {
        Ok(outcome) => outcome,
        Err(error) => {
            tracing::error!("database error persisting deal: {error}");
            return error_json(
                StatusCode::INTERNAL_SERVER_ERROR,
                json!({ "error": "internal error" }),
            )
            .into_response();
        }
    };

    let stored = insert_outcome.deal;

    // The remote contract and local payment intent are durable. Convert the
    // spend hold to committed before moving money; a failure here remains
    // counted as external-pending.
    if let Some(guard) = spend_guard.take() {
        guard.commit(&stored.deal_id).await;
    }

    // ── Buyer-side prepaid Lightning payment ───────────────────────────────
    // Only the transaction that created the durable requester record may pay.
    // An identical provider retry reuses the record and never pays twice.
    if insert_outcome.created
        && let Some(invoice) = prepaid_invoice.as_ref()
    {
        let buyer_phoenixd = state
            .config
            .buyer_phoenixd
            .as_ref()
            .expect("prepaid config checked before persistence");
        match settlement::pay_buyer_prepaid_invoice(buyer_phoenixd, &invoice.bolt11).await {
            Ok(sent) => {
                if let Err(error) = settlement::phoenixd::validate_prepaid_payment_proof(
                    &invoice.payment_hash,
                    invoice.amount_sat,
                    &settlement::phoenixd::IncomingPayment {
                        is_paid: true,
                        preimage_hex: sent.preimage_hex,
                        received_sat: invoice.amount_sat,
                    },
                ) {
                    tracing::error!(
                        deal_id = %stored.deal_id,
                        "prepaid payment proof did not match the invoice: {error}"
                    );
                    return error_json(
                        StatusCode::BAD_GATEWAY,
                        json!({ "error": "prepaid payment proof did not match the invoice" }),
                    )
                    .into_response();
                }
                if sent.payment_hash_hex.to_lowercase() != invoice.payment_hash.to_lowercase() {
                    return error_json(
                        StatusCode::BAD_GATEWAY,
                        json!({ "error": "prepaid wallet returned a different payment hash" }),
                    )
                    .into_response();
                }
            }
            Err(error) => {
                tracing::error!("Buyer prepaid Lightning payment failed: {error}");
                return error_json(
                    StatusCode::SERVICE_UNAVAILABLE,
                    json!({
                        "error": format!(
                            "failed to pay the prepaid Lightning invoice for this deal: {error}"
                        )
                    }),
                )
                .into_response();
            }
        }
    }

    let stored = match sync_requester_deal_from_provider(state.clone(), &stored.deal_id).await {
        Ok(synced) => synced.deal,
        Err(_) => stored,
    };
    let mut payment_intent = None;
    if quote_uses_lightning_bundle(state.as_ref(), &stored.quote) {
        match load_runtime_requester_deal_and_payment_intent(state.clone(), &stored.deal_id).await {
            Ok((_deal, intent)) => payment_intent = intent,
            Err(error) => return error_json(error.0, error.1).into_response(),
        }
    }

    (
        StatusCode::OK,
        Json(json!(RuntimeCreateDealResponse {
            provider_id: stored.provider_id.clone(),
            provider_url: stored.provider_url.clone(),
            quote: stored.quote.clone(),
            deal: stored.public_record(),
            payment_intent_path: payment_intent
                .as_ref()
                .map(|intent| runtime_payment_intent_path(&intent.deal_id)),
            payment_intent,
        })),
    )
        .into_response()
}

