fn accepted_payment_methods(state: &AppState) -> Vec<String> {
    settlement::accepted_payment_methods(state)
        .into_iter()
        .filter(|method| method != "x402_usdc")
        .collect()
}

fn grant_requested_capabilities_from_offer(
    spec: &WorkloadSpec,
    offer: &SignedArtifact<OfferPayload>,
) -> Result<Vec<String>, (StatusCode, Json<serde_json::Value>)> {
    let requested = spec.requested_capabilities();
    if requested.is_empty() {
        return Ok(Vec::new());
    }

    for capability in requested {
        if !offer
            .payload
            .execution_profile
            .capabilities
            .iter()
            .any(|granted| granted == capability)
        {
            return Err(error_json(
                StatusCode::BAD_REQUEST,
                json!({
                    "error": "offer does not grant requested capability",
                    "capability": capability,
                    "offer_id": offer.payload.offer_id,
                }),
            ));
        }
    }

    Ok(requested.to_vec())
}

fn mount_access_capabilities(mounts: &[ExecutionMount]) -> Vec<String> {
    mounts
        .iter()
        .map(|mount| {
            format!(
                "mount.{}.{}.{}",
                mount.kind,
                if mount.read_only { "read" } else { "write" },
                mount.handle
            )
        })
        .collect()
}

fn merged_access_capabilities(definition: &ProviderManagedOfferDefinition) -> Vec<String> {
    let mut capabilities = definition.capabilities.clone();
    capabilities.extend(mount_access_capabilities(&definition.mounts));
    capabilities.sort();
    capabilities.dedup();
    capabilities
}

fn service_access_capabilities(service: &ProviderServiceRecord) -> Vec<String> {
    let mut capabilities = service.capabilities.clone();
    capabilities.extend(mount_access_capabilities(&service.mounts));
    capabilities.sort();
    capabilities.dedup();
    capabilities
}

fn capability_requires_gpu(capability: &str) -> bool {
    capability == "compute.gpu" || capability.starts_with("compute.gpu.")
}

fn capabilities_include_gpu(capabilities: &[String]) -> bool {
    capabilities
        .iter()
        .any(|capability| capability_requires_gpu(capability))
}

fn validate_gpu_capabilities_supported_by_execution(
    execution: &ExecutionWorkload,
    capabilities: &[String],
) -> Result<(), String> {
    if !capabilities_include_gpu(capabilities) {
        return Ok(());
    }
    match (&execution.runtime, &execution.package_kind) {
        (ExecutionRuntime::Container, ExecutionPackageKind::OciImage)
        | (ExecutionRuntime::Python, ExecutionPackageKind::OciImage) => Ok(()),
        _ => Err(
            "GPU capability requires container OCI execution; refusing to fall back to CPU"
                .to_string(),
        ),
    }
}

fn validate_provider_offer_capabilities_for_node(
    state: &AppState,
    capabilities: &[String],
) -> Result<(), String> {
    let advertised_gpu_capabilities = state.config.gpu.advertised_capabilities();
    for capability in capabilities {
        if !capability_requires_gpu(capability) {
            continue;
        }
        if !state.config.gpu.enabled {
            return Err(
                "GPU capabilities require FROGLET_GPU_ENABLED=1 on this provider".to_string(),
            );
        }
        if !advertised_gpu_capabilities
            .iter()
            .any(|advertised| advertised == capability)
        {
            return Err(format!(
                "GPU capability {capability} is not advertised by this provider"
            ));
        }
    }
    Ok(())
}

fn current_provider_capability_available(state: &AppState, capability: &str) -> bool {
    if capability_requires_gpu(capability) {
        return state
            .config
            .gpu
            .advertised_capabilities()
            .iter()
            .any(|advertised| advertised == capability);
    }

    if let Some(host_env) = state.wasm_host.as_ref() {
        let wasm_host_capabilities = host_env.advertised_capabilities();
        if wasm_host_capabilities
            .iter()
            .any(|advertised| advertised == capability)
        {
            return true;
        }
    }

    // Non-provider-wide capabilities such as mount handles are validated
    // against the selected offer before the quote is issued.
    true
}

fn local_wasm_capabilities_for_submission(
    state: &AppState,
    submission: &wasm::VerifiedWasmSubmission,
) -> Result<
    (
        Vec<String>,
        Option<Arc<crate::wasm_host::WasmHostEnvironment>>,
    ),
    String,
> {
    match submission.abi_version.as_str() {
        wasm::WASM_RUN_JSON_ABI_V1 => Ok((Vec::new(), None)),
        wasm::WASM_HOST_JSON_ABI_V1 => {
            let Some(host_environment) = state.wasm_host.clone() else {
                return Err("froglet.wasm.host_json.v1 is not enabled on this provider".to_string());
            };
            let offered = host_environment.advertised_capabilities();
            for capability in &submission.requested_capabilities {
                if !offered.iter().any(|offered| offered == capability) {
                    return Err(format!(
                        "requested_capability '{capability}' is not enabled on this provider"
                    ));
                }
            }
            Ok((
                submission.requested_capabilities.clone(),
                Some(host_environment),
            ))
        }
        other => Err(format!("unsupported wasm abi_version: {other}")),
    }
}

async fn quoted_settlement_terms(
    state: &AppState,
    price_sats: u64,
) -> Result<QuoteSettlementTerms, String> {
    if let Some(terms) = settlement::quoted_lightning_settlement_terms(state, price_sats).await? {
        return Ok(terms);
    }

    // Stripe MPP: when Stripe is the active paid backend and the service has
    // a non-zero price, return stripe_mpp.v1 settlement terms.  Lightning-
    // specific fields (invoice expiry, CLTV, destination_identity) are zeroed
    // because Stripe does not use hold invoices.
    if price_sats > 0
        && state
            .config
            .payment_backends
            .contains(&PaymentBackend::Stripe)
    {
        let base_fee_msat = price_sats
            .checked_mul(1_000)
            .ok_or_else(|| "quote price exceeds the millishatoshi range".to_string())?;
        return Ok(QuoteSettlementTerms {
            method: "stripe_mpp.v1".to_string(),
            destination_identity: String::new(),
            base_fee_msat,
            success_fee_msat: 0,
            max_base_invoice_expiry_secs: 0,
            max_success_hold_expiry_secs: 0,
            min_final_cltv_expiry: 0,
        });
    }

    if price_sats > 0 {
        return Err(
            "priced Kernel deals require a configured Lightning or Stripe settlement backend; \
             x402 is available only through the direct HTTP payment endpoint"
                .to_string(),
        );
    }

    // Canonical free-service settlement terms: method "none" with empty
    // destination_identity and zero fees.  Do NOT fall through to the
    // Lightning method string with zero fees.
    Ok(QuoteSettlementTerms {
        method: "none".to_string(),
        destination_identity: String::new(),
        base_fee_msat: 0,
        success_fee_msat: 0,
        max_base_invoice_expiry_secs: 0,
        max_success_hold_expiry_secs: 0,
        min_final_cltv_expiry: 0,
    })
}

fn settlement_quote_expires_at(
    state: &AppState,
    created_at: i64,
    price_sats: u64,
    execution_window_secs: u64,
) -> i64 {
    settlement::lightning_quote_expires_at(state, created_at, price_sats, execution_window_secs)
}

fn sign_node_artifact<T: Serialize + Clone>(
    state: &AppState,
    kind: &str,
    created_at: i64,
    payload: T,
) -> Result<SignedArtifact<T>, String> {
    protocol::sign_artifact(
        state.identity.node_id(),
        |message| state.identity.sign_message_hex(message),
        kind,
        created_at,
        payload,
    )
}

async fn persist_signed_artifact<T>(
    state: &AppState,
    kind: &str,
    payload: T,
) -> Result<SignedArtifact<T>, String>
where
    T: Serialize + DeserializeOwned + Clone + Send + 'static,
{
    let created_at = settlement::current_unix_timestamp();
    let artifact = sign_node_artifact(state, kind, created_at, payload)?;
    let actor_id = artifact.signer.clone();
    let kind = artifact.artifact_type.clone();
    let payload_hash = artifact.payload_hash.clone();
    let artifact_hash = artifact.hash.clone();
    let document_json = serde_json::to_string(&artifact).map_err(|e| e.to_string())?;

    let stored = state
        .db
        .with_write_conn(move |conn| {
            db::insert_artifact_document(
                conn,
                &artifact_hash,
                &payload_hash,
                &kind,
                &actor_id,
                created_at,
                &document_json,
            )?;
            db::get_artifact_by_actor_kind_payload(conn, &actor_id, &kind, &payload_hash)
        })
        .await?
        .ok_or_else(|| "artifact missing after insert".to_string())?;

    serde_json::from_value(stored.document).map_err(|e| e.to_string())
}

