        assert_eq!(payload["execution"]["gpu"]["vendor"], "NVIDIA");
        assert_eq!(payload["execution"]["gpu"]["model"], "L4");
        assert_eq!(payload["execution"]["gpu"]["memory_mb"], 24_576);
