    #[tokio::test]
    async fn published_service_capabilities_flow_to_service_offer_and_execution() {
        let mut state = test_app_state(PaymentBackend::None);
        let fixtures_dsn = "postgres://reader:secret@db.internal:5432/fixtures";
        Arc::get_mut(&mut state)
            .expect("unique app state")
            .config
            .postgres_mounts
            .insert("fixtures".to_string(), fixtures_dsn.to_string());

        publish_test_service(
            &state,
            ProviderControlPublishArtifactRequest {
                service_id: "cap-python".to_string(),
                offer_id: None,
                artifact_path: None,
                wasm_module_hex: None,
                oci_reference: None,
                oci_digest: None,
                runtime: Some("python".to_string()),
                package_kind: Some("inline_source".to_string()),
                entrypoint_kind: Some("handler".to_string()),
                entrypoint: Some("handler".to_string()),
                contract_version: Some(CONTRACT_PYTHON_HANDLER_JSON_V1.to_string()),
                mounts: Some(vec![froglet_protocol::publication::PublicationMount {
                    handle: "fixtures".to_string(),
                    kind: "postgres".to_string(),
                    read_only: true,
                    binding: None,
                }]),
                capabilities: Some(vec!["custom.vector-index".to_string()]),
                inline_source: Some("def handler(event, context):\n    return event\n".to_string()),
                summary: Some("capability carrying service".to_string()),
                starter: None,
                mode: Some("sync".to_string()),
                price_sats: 0,
                price_currency: None,
                publication_state: Some("active".to_string()),
                input_schema: None,
                output_schema: None,
                ..Default::default()
            },
        )
        .await;

        let service = provider_service_record(state.as_ref(), "cap-python", false, false)
            .await
            .expect("service record")
            .expect("published service");
        assert_eq!(service.mounts.len(), 1);
        assert_eq!(service.mounts[0].binding, None);
        assert_eq!(
            service.capabilities,
            vec!["custom.vector-index".to_string()]
        );

        let private_service = provider_service_record(state.as_ref(), "cap-python", false, true)
            .await
            .expect("private service record")
            .expect("published service");
        assert_eq!(private_service.mounts.len(), 1);
        assert_eq!(
            private_service.mounts[0].binding.as_deref(),
            Some(fixtures_dsn)
        );

        let offer = provider_control_offer_record(state.as_ref(), &service.offer_id, true)
            .await
            .expect("offer record")
            .expect("published offer");
        assert_eq!(offer.capabilities, vec!["custom.vector-index".to_string()]);
        assert_eq!(
            offer.offer.payload.execution_profile.capabilities,
            vec![
                "custom.vector-index".to_string(),
                "mount.postgres.read.fixtures".to_string()
            ]
        );

        let execution = service_addressed_execution_from_record(&service, Value::Null);
        assert_eq!(execution.mounts.len(), 1);
        assert_eq!(execution.mounts[0].binding, None);
        assert_eq!(
            execution.requested_access,
            vec![
                "custom.vector-index".to_string(),
                "mount.postgres.read.fixtures".to_string()
            ]
        );
    }

    fn service_addressed_execution_from_record(
        service: &ProviderServiceRecord,
        input: Value,
    ) -> crate::execution::ExecutionWorkload {
        let (runtime, package_kind, entrypoint_kind, entrypoint, contract_version) =
            normalized_service_execution_profile(service).expect("normalized service profile");
        let input_hash =
            crypto::sha256_hex(canonical_json::to_vec(&input).expect("canonical input"));
        let requested_access = service_access_capabilities(service);
        let binding_hash = service
            .binding_hash
            .clone()
            .or_else(|| service.module_hash.clone())
            .expect("binding hash");
        let mut execution = crate::execution::ExecutionWorkload {
            schema_version: FROGLET_SCHEMA_V1.to_string(),
            workload_kind: crate::execution::WORKLOAD_KIND_EXECUTION_V1.to_string(),
            runtime,
            package_kind,
            entrypoint: crate::execution::ExecutionEntrypoint {
                kind: entrypoint_kind,
                value: entrypoint,
            },
            contract_version,
            input_format: JCS_JSON_FORMAT.to_string(),
            input_hash,
            requested_access,
            security: crate::execution::ExecutionSecurity {
                mode: crate::execution::ExecutionSecurityMode::Standard,
                confidential_session_hash: None,
                service_id: Some(service.service_id.clone()),
                request_envelope: None,
            },
            mounts: service.mounts.clone(),
            input,
            module_hash: None,
            module_bytes_hex: None,
            source_hash: None,
            inline_source: None,
            python_bundle: None,
            oci_reference: None,
            oci_digest: None,
            builtin_name: None,
        };
        match execution.package_kind {
            crate::execution::ExecutionPackageKind::InlineSource => {
                execution.source_hash = Some(binding_hash)
            }
            crate::execution::ExecutionPackageKind::InlineModule
            | crate::execution::ExecutionPackageKind::OciImage => {
                execution.module_hash = Some(binding_hash)
            }
            crate::execution::ExecutionPackageKind::Builtin => {
                execution.workload_kind = service.offer_kind.clone();
                execution.builtin_name = Some(execution.entrypoint.value.clone());
                execution.module_hash = Some(binding_hash);
            }
        }
        execution
    }

