    #[test]
    fn unsigned_provider_projection_only_allows_forward_nonterminal_observations() {
        assert!(unsigned_provider_transition_is_forward(
            deals::DEAL_STATUS_PAYMENT_PENDING,
            deals::DEAL_STATUS_RESULT_READY,
        ));
        assert!(unsigned_provider_transition_is_forward(
            deals::DEAL_STATUS_RUNNING,
            deals::DEAL_STATUS_RESULT_READY,
        ));
        assert!(!unsigned_provider_transition_is_forward(
            deals::DEAL_STATUS_RESULT_READY,
            deals::DEAL_STATUS_RUNNING,
        ));
        assert!(!unsigned_provider_transition_is_forward(
            deals::DEAL_STATUS_ACCEPTED,
            deals::DEAL_STATUS_SUCCEEDED,
        ));
    }

    #[test]
    fn marketplace_quote_verifier_rejects_tampered_quote() {
        let mut quote = signed_quote(
            "requester".to_string(),
            1_700_000_000,
            1_700_000_060,
            1_000,
            30,
            30,
        );
        quote.payload.workload_hash = "dd".repeat(32);

        let error =
            verify_marketplace_quote_artifact(quote).expect_err("tampered quote must be rejected");

        assert!(
            error.contains("signature verification failed"),
            "unexpected error: {error}"
        );
    }

