    #[tokio::test]
    async fn hosted_trial_public_router_accepts_session_token_for_demo_runtime_flow() {
        let state = test_app_state_with_session_pool(PaymentBackend::None);
        crate::builtins::register_demo_offers(state.as_ref())
            .await
            .expect("register demo offers");
        let provider = spawn_public_test_server(state.clone()).await;
        let _env_lock = TEST_ENV_LOCK.lock().await;
        let _env = ScopedEnvVar::set("FROGLET_RUNTIME_PROVIDER_BASE_URL", &provider.base_url);
        let session_token = issue_test_session_token(&state);
        let public = public_router(state.clone());

        let create_response = public
            .clone()
            .oneshot(hosted_trial_runtime_request(
                Method::POST,
                "/v1/runtime/deals",
                Some(&session_token),
                Some(test_runtime_demo_add_create_deal_request(
                    state.identity.node_id(),
                    &provider.base_url,
                    "hosted-trial-session-token",
                )),
            ))
            .await
            .expect("hosted-trial create deal response");
        let (create_status, create_payload): (StatusCode, RuntimeCreateDealResponse) =
            response_json(create_response).await;
        assert_eq!(create_status, StatusCode::OK);

        let get_response = public
            .clone()
            .oneshot(hosted_trial_runtime_request(
                Method::GET,
                &format!("/v1/runtime/deals/{}", create_payload.deal.deal_id),
                Some(&session_token),
                None,
            ))
            .await
            .expect("hosted-trial get deal response");
        let (get_status, get_payload): (StatusCode, RuntimeDealResponse) =
            response_json(get_response).await;
        assert_eq!(get_status, StatusCode::OK);
        assert_eq!(get_payload.deal.deal_id, create_payload.deal.deal_id);
        assert_eq!(get_payload.deal.status, "succeeded");
        assert_eq!(get_payload.deal.result, Some(json!({ "sum": 12 })));
        assert!(get_payload.deal.result_hash.is_some());
        assert!(get_payload.deal.receipt.is_some());
        assert_eq!(get_payload.deal.quote.artifact_type, ARTIFACT_KIND_QUOTE);

        let feed_response = public
            .oneshot(runtime_request(
                Method::GET,
                "/v1/feed?limit=100",
                None,
                None,
            ))
            .await
            .expect("hosted-trial feed response");
        let (feed_status, feed_payload): (StatusCode, Value) = response_json(feed_response).await;
        assert_eq!(feed_status, StatusCode::OK);
        assert!(feed_payload["artifacts"].is_array());
        assert_eq!(feed_payload["cursor_type"], "artifact_sequence");
        assert!(feed_payload["cursor_semantics"].is_string());
        assert!(feed_payload["applied_cursor"].is_number());
        assert!(feed_payload["page_size"].is_number());
        assert!(feed_payload["has_more"].is_boolean());
        assert!(
            feed_payload.get("events").is_none(),
            "feed must expose artifacts, not events: {feed_payload}"
        );
        assert!(
            feed_payload.get("items").is_none(),
            "feed must expose artifacts, not items: {feed_payload}"
        );
        let artifact_kinds = feed_payload["artifacts"]
            .as_array()
            .expect("feed artifacts")
            .iter()
            .filter_map(|artifact| artifact["kind"].as_str())
            .collect::<std::collections::HashSet<_>>();
        assert!(
            artifact_kinds.contains(ARTIFACT_KIND_DESCRIPTOR),
            "missing descriptor artifact: {feed_payload}"
        );
        assert!(
            artifact_kinds.contains(ARTIFACT_KIND_OFFER),
            "missing offer artifact: {feed_payload}"
        );
        assert!(
            artifact_kinds.contains(ARTIFACT_KIND_RECEIPT),
            "missing receipt artifact: {feed_payload}"
        );
    }

    #[tokio::test]
    async fn hosted_trial_create_deal_quota_is_keyed_by_request_origin() {
        let mut state = test_app_state_with_session_pool(PaymentBackend::None);
        {
            let state_mut = Arc::get_mut(&mut state).expect("unique app state");
            state_mut
                .config
                .public_quota
                .hosted_trial_deals_per_identity = 1;
            state_mut.config.public_quota.hosted_trial_window_secs = 300;
            state_mut.hosted_trial_deal_quota = Some(Arc::new(
                crate::public_quota::IdentityQuota::new(1, Duration::from_secs(300)),
            ));
        }
        crate::builtins::register_demo_offers(state.as_ref())
            .await
            .expect("register demo offers");
        let provider = spawn_public_test_server(state.clone()).await;
        let _env_lock = TEST_ENV_LOCK.lock().await;
        let _env = ScopedEnvVar::set("FROGLET_RUNTIME_PROVIDER_BASE_URL", &provider.base_url);
        let first_session_token = issue_test_session_token(&state);
        let second_session_token = issue_test_session_token(&state);
        let public = public_router(state.clone());

        let first_response = public
            .clone()
            .oneshot(hosted_trial_runtime_request(
                Method::POST,
                "/v1/runtime/deals",
                Some(&first_session_token),
                Some(test_runtime_demo_add_create_deal_request(
                    state.identity.node_id(),
                    &provider.base_url,
                    "hosted-trial-quota-first",
                )),
            ))
            .await
            .expect("first hosted-trial create deal response");
        let (first_status, _first_payload): (StatusCode, Value) =
            response_json(first_response).await;
        assert_eq!(first_status, StatusCode::OK);

        let mut second_request = hosted_trial_runtime_request(
            Method::POST,
            "/v1/runtime/deals",
            Some(&second_session_token),
            Some(test_runtime_demo_add_create_deal_request(
                state.identity.node_id(),
                &provider.base_url,
                "hosted-trial-quota-second",
            )),
        );
        second_request
            .headers_mut()
            .insert("x-forwarded-for", HeaderValue::from_static("203.0.113.10"));
        let second_response = public
            .oneshot(second_request)
            .await
            .expect("second hosted-trial create deal response");
        let (second_status, second_payload): (StatusCode, Value) =
            response_json(second_response).await;
        assert_eq!(second_status, StatusCode::TOO_MANY_REQUESTS);
        assert_eq!(
            second_payload["error"],
            "hosted trial create-deal quota exceeded"
        );
        assert!(second_payload["retry_after_secs"].is_number());
    }

